import axios from "axios";
import MaterialTable from "material-table";
import React, { Component } from "react";
import { connect } from "react-redux";
import { Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";
import { changePage } from "../../actions/pageActions";

class Clients extends Component {
  state = {
    rowData: [],
    tableLoaded: true
  };

  componentDidMount() {
    this.retrieveFromDb();
  }

  retrieveFromDb = () => {
    this.setState(state => ({
      tableLoaded: false,
      rowData: state.rowData
    }));
    axios
      .get("/api/userAccessTypes")
      .then(res => {
        var rowData = res.data.map((x, index) => {
          return {
            id: x._id,
            name: x.name
          };
        });
        this.setState(state => ({
          tableLoaded: true,
          rowData
        }));
      })
      .catch(err => console.log(err));
  };

  onPageChangeClick = (navType, page) => {
    const pageDetail = {
      navType,
      page
    };
    this.props.changePage(pageDetail);
  };

  render() {
    return (
      <div>
        {this.state.tableLoaded ? (
          <MaterialTable
            columns={[
              { title: "ID", field: "id", editable: "never" },
              { title: "Name", field: "name" }
            ]}
            data={this.state.rowData}
            title={"Create User Access Tdfsype"}
            options={{
              actionsColumnIndex: 2,
              addRowPosition: "first"
            }}
            /*actions={[
              {
                icon: "delete",
                tooltip: "Delete User",
                disabled: true
              },{
                icon: "add",
                tooltip: "add",
                disabled: true
              },
            ]}*/
            onRowClick={(rowdata, event) => {
              //console.log(event.id);
              this.onPageChangeClick("ClientsNav", event.id);
            }}
            //
            editable={{
              onRowAdd: newData =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      this.setState(state => ({
                        tableLoaded: false,
                        rowData: state.rowData
                      }));
                      const newClient = {
                        name: newData.name
                      };
                      axios
                        .post(
                          "/api/userAccessTypes",
                          newClient,
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveFromDb();
                          this.setState(state => ({
                            tableLoaded: true,
                            rowData: state.rowData
                          }));
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 10);
                }),
              onRowUpdate: (newData, oldData) =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      this.setState(state => ({
                        tableLoaded: false,
                        rowData: state.rowData
                      }));
                      axios
                        .put(
                          `/api/userAccessTypes/${newData.id}`,
                          { name: newData.name },
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveFromDb();
                          this.setState(state => ({
                            tableLoaded: true,
                            rowData: state.rowData
                          }));
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 1000);
                }),
              onRowDelete: oldData =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      this.setState(state => ({
                        tableLoaded: false,
                        rowData: state.rowData
                      }));
                      axios
                        .delete(
                          `/api/userAccessTypes/${oldData.id}`,
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveFromDb();
                          this.setState(state => ({
                            tableLoaded: true,
                            rowData: state.rowData
                          }));
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 1000);
                })
            }}
            //////
          />
        ) : (
          <div
            style={{
              display: "flex",
              justifyContent: "center"
            }}
          >
            <Spinner animation="border" />
          </div>
        )}
      </div>
    );
  }
}

const mapStateToProps = state => ({
  auth: state.auth
});

export default connect(mapStateToProps, { changePage })(Clients);
